#!/usr/bin/env python3
"""Generate LucideIcons.g.cs using only the SVGs vendored in Icons/."""

from pathlib import Path


ROOT = Path(__file__).resolve().parent


def main():
    icons = [
        (svg, "".join(part.capitalize() for part in svg.stem.split("-")))
        for svg in sorted((ROOT / "Icons").glob("*.svg"))
    ]
    lines = [
        "// <auto-generated />",
        "// Regenerate with generate.py.",
        "using AwAUI.Svg;",
        "",
        "namespace AwAUI.Icons.Lucide;",
        "",
        "/// <summary>A curated set of Lucide icons for AwAUI.</summary>",
        "/// <remarks>Each document is parsed on first access and shared by subsequent callers.</remarks>",
        "public static class LucideIcons",
        "{",
    ]
    for svg, name in icons:
        lines.extend([
            f"    /// <summary>Gets the Lucide <c>{svg.stem}</c> icon.</summary>",
            f"    public static SvgDocument {name} => {name}Cache.Document;",
            "",
        ])
    lines.extend([
        '    /// <summary>Gets the <see cref="Ellipsis"/> icon (Lucide alias <c>more-horizontal</c>).</summary>',
        "    public static SvgDocument MoreHorizontal => Ellipsis;",
        "",
        "    // Explicit static constructors give each icon independent, thread-safe initialization.",
    ])
    for svg, name in icons:
        source = svg.read_text(encoding="utf-8").rstrip("\n")
        if '"""' in source:
            raise ValueError(f"{svg.name} contains the C# raw string delimiter")
        lines.extend([
            f"    static class {name}Cache",
            "    {",
            "        internal static readonly SvgDocument Document;",
            "",
            f'        static {name}Cache() => Document = SvgDocument.Parse("""',
            *(f"            {line}" if line else "" for line in source.split("\n")),
            '            """);',
            "    }",
            "",
        ])
    lines[-1] = "}"
    lines.append("")
    (ROOT / "Generated" / "LucideIcons.g.cs").write_bytes("\n".join(lines).encode("utf-8"))


if __name__ == "__main__":
    main()
